function showNotice(text,tone){el('notice-text').textContent=text;el('notice').dataset.tone=tone||'';el('notice').hidden=false}
let versionTarget='';
function buttons(){const il=!connected||!state?.running||!!pending||!!state?.busy||!!state?.approvals?.some(a=>a.status==='pending')||!!state?.versions?.operation;for(const id of ['instance-choose','instance-select','instance-cpu','instance-memory','instance-disk','instance-apply'])el(id).disabled=il;const vl=!connected||!!pending||!!state?.busy||!!state?.approvals?.some(a=>a.status==='pending')||!!state?.versions?.operation;el('upgrade-version').disabled=vl||state?.versions?.current==='v2'||!state?.versions?.available?.includes('v2');el('upgrade-version').hidden=false;el('upgrade-version').textContent=state?.versions?.current==='v2'?'已是最新版本':'发现新版本，升级';el('switch-version').disabled=vl;el('version-select').disabled=vl;el('version-apply').disabled=vl;el('version-safety').disabled=!connected||!!pending||!state?.versions?.operation; el('new-session').disabled=!connected||!!pending||!!state?.versions?.operation||!!state?.busy||state?.sessionsSupported!==true;el('session-select').disabled=el('new-session').disabled;el('preview-open').disabled=!connected||!!pending||!!state?.versions?.operation;el('preview-close').disabled=!connected||!!pending||el('preview-frame').hidden;el('wake').disabled=!connected||!!pending||!!state?.versions?.operation||!state||state.running||!state.checkpointAt;const busy=!!(state&&state.busy);const locked=!connected||!!pending||!!state?.versions?.operation;el('send').disabled=locked||busy||!el('prompt').value.trim();el('save').disabled=locked||busy||!state||!state.running;el('snapshot-create').disabled=el('save').disabled;el('restart').disabled=el('save').disabled||!state?.checkpointAt;el('restart-apply').disabled=el('restart').disabled;el('recover').disabled=locked||!state||busy||state.hasBackup!==true;el('confirm-restore').disabled=el('recover').disabled;el('send-label').textContent=pending==='submit'?'正在提交…':busy?'任务执行中':'执行任务';el('save-label').textContent=pending==='save'?'正在保存…':'保存并休眠';el('confirm-restore').textContent=pending==='recover'?'正在恢复…':'确认恢复';document.querySelectorAll('[data-prompt]').forEach(function(b){b.disabled=!!pending||busy});if(busy)el('confirm-recovery').hidden=true}
async function api(path,body){const r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(r.status===401||r.status===403)throw Error('登录失效或访问被拒绝。请刷新页面，重新通过 Access 验证。');if(r.redirected)throw Error('需要重新登录，请刷新页面完成 Access 验证。');const text=await r.text();let data;try{data=JSON.parse(text)}catch{throw Error('服务器未返回有效数据（HTTP '+r.status+'）。请查看 Worker 日志。')}if(!r.ok)throw Error(data.error||'操作失败（HTTP '+r.status+'）');return data}
function render(s){renderInstance(s.instance);renderVersion(s.versions);renderSessions(s);const previousTask=state?.task?.id;state=s;if(previousTask!==s.task?.id){el('evidence-desktop').hidden=true;el('evidence-mobile').hidden=true;el('evidence-report').textContent='';el('evidence-note').textContent='等待本次 Agent 自检结果与真实截图。';}renderApprovals(s.approvals||[]);if(s.running&&s.task?.status==='completed'&&(s.preview||s.task.id===submittedId)&&s.task.prompt?.includes('node /app/site-check.mjs review-deck')&&!autoSites.has(s.task.id)){autoSites.add(s.task.id);queueMicrotask(()=>void showWebsite(s.task,s.preview));}renderSpeed(s);el('runtime-label').textContent=s.busy?'任务执行中':s.running?'环境运行中':'环境已停止';el('runtime-status').dataset.tone=s.busy?'busy':s.running?'good':'';el('runtime-note').textContent=s.busy?'':s.running?'空闲约 10 分钟后自动保存并休眠。':s.checkpointAt?'提交任务或点击唤醒以继续。':'提交任务以启动环境。';el('checkpoint-time').textContent=s.checkpointAt?date(s.checkpointAt):'尚无快照';el('backup-time').textContent=s.hasBackup?(s.backupAt?date(s.backupAt):'已有备份，时间未记录'):'尚无 R2 备份';el('checkpoint-error').hidden=!s.checkpointError;el('checkpoint-error').textContent=s.checkpointError?'保存错误：'+s.checkpointError:'';el('recovery-hint').textContent=s.busy?'任务执行中，请结束后再恢复。':s.hasBackup?'恢复会覆盖容器内的文件与对话数据，请先确认。':'尚无成功的 R2 备份，请先保存。';el('diagnostics').textContent=JSON.stringify({running:s.running,busy:s.busy,checkpointAt:s.checkpointAt,checkpointError:s.checkpointError,hasBackup:s.hasBackup,idleShutdownAt:s.idleShutdownAt,modelConfig:s.modelConfig,lastGatewayError:s.lastGatewayError,lastBrowserCheck:s.lastBrowserCheck,lastBoot:s.lastBoot,responseTiming:s.responseTiming,bridgeVersion:s.bridgeVersion,runtimeReady:s.runtimeReady,task:s.task?{id:s.task.id,status:s.task.status,finishReason:s.task.finishReason,startedAt:s.task.startedAt,error:s.task.error}:null},null,2);const t=s.task;el('empty').hidden=!!t;el('task-content').hidden=!t;el('task-meta').hidden=!t;if(t){const failed=t.status==='failed';const active=t.status==='running';el('task-badge').textContent=labels[t.status]||t.status||'状态未知';el('task-badge').dataset.tone=failed?'bad':active?'busy':t.status==='completed'?'good':'';el('task-heading').textContent=failed?'这次任务没有完成':active?'Agent 正在处理任务':t.status==='completed'?'任务已完成':t.status==='interrupted'?'任务已中断，未自动重放':'请核实任务状态';el('task-error').hidden=!failed&&!t.error;const gatewayFailure=failed&&s.lastGatewayError&&Number(s.lastGatewayError.at)>=Number(t.startedAt)&&(!t.finishedAt||Number(s.lastGatewayError.at)<=Number(t.finishedAt))?s.lastGatewayError:null;el('task-error-text').textContent=gatewayFailure?('模型调用失败：'+gatewayFailure.message+'\n网关：'+gatewayFailure.gateway+' / 模型：'+gatewayFailure.model+(gatewayFailure.code?'\n错误码：'+gatewayFailure.code:'')):(t.error||'这次任务没有返回具体错误，请查看诊断信息或 Worker 日志。');el('output').textContent=active&&s.live?.taskId===t.id?s.live.text||'':t.response||'';el('waiting').hidden=!active;el('task-time').textContent='开始于 '+date(t.startedAt);el('task-id').textContent='ID '+t.id;const key=t.id+':'+t.status;if(lastTaskKey&&key!==lastTaskKey&&!pending&&failed)showNotice('最近一次任务失败，具体信息请查看执行结果。','bad');lastTaskKey=key}else{el('task-badge').textContent='等待任务';el('task-badge').dataset.tone=''}const hk=JSON.stringify([s.sessionId,s.running,s.checkpointAt,t&&t.id,t&&t.status]);if(hk!==historyKey&&!historyLoading){historyKey=hk;void loadHistory()}syncStream(s);buttons()}
function instanceText(v){return typeof v==='string'?v:v?v.vcpu+' CPU / '+v.memoryMib+' MiB / '+v.diskMb+' MB':'未知'}
const instancePresets={'lite':{vcpu:1/16,memoryMib:256,diskMb:2000},'standard-1':{vcpu:0.5,memoryMib:4096,diskMb:8000},'standard-2':{vcpu:1,memoryMib:6144,diskMb:12000},'standard-3':{vcpu:2,memoryMib:8192,diskMb:16000},'standard-4':{vcpu:4,memoryMib:12288,diskMb:20000}};
function renderInstance(i){const v=typeof i?.current==='string'?instancePresets[i.current]:i?.current;el('instance-cpu-current').textContent=v?v.vcpu+' vCPU':'—';el('instance-memory-current').textContent=v?(v.memoryMib%1024===0?v.memoryMib/1024+' GiB':v.memoryMib+' MiB'):'—';el('instance-disk-current').textContent=v?v.diskMb/1000+' GB':'—';for(const id of ['instance-cpu-current','instance-memory-current','instance-disk-current'])el(id).title=i?.source==='checkpoint'?'已保存配置':'启动配置';}
